namespace {struct FGuidePage{const TCHAR* CN;const TCHAR* EN;const TCHAR* LinesCN[8];const TCHAR* LinesEN[8];};const FGuidePage Pages[]={
{TEXT("街区争夺：招募与指挥"),TEXT("STREET WAR: RECRUIT & COMMAND"), {TEXT("初始600现金和一名老大；空格开始战斗。"),TEXT("2跑腿80；3刀兵120；4铁棍180；5投掷220；6盲盒130。"),TEXT("Z/X/C选择上、中、下路，只影响之后招募的出兵路线。"),TEXT("俯视右键选老大或士兵，右键拖框多选，Shift追加。"),TEXT("右键地面下令移动；右键敌人或敌方基地车指定攻击。"),TEXT("F守位；G跟随；B回基地；H护送；V突袭；1选老大。"),TEXT("兵种名位于血条上方；附近道具自动拾取且只可使用一次。"),TEXT("F1打开指南；ESC暂停；N重新开局；主菜单切换模式。")}, {TEXT("Start with 600 cash and a boss. SPACE starts battle."),TEXT("2 Runner 80 / 3 Blade 120 / 4 Baton 180 / 5 Thrower 220 / 6 Box 130."),TEXT("Z / X / C sets the lane for FUTURE recruits; it does not redirect existing units."),TEXT("Overhead: RMB selects a boss or soldier; drag RMB for squads; SHIFT adds."),TEXT("RMB ground to move; RMB an enemy or enemy van to focus attacks."),TEXT("F hold / G follow / B return / H escort / V raid / 1 select boss."),TEXT("Role names appear above health bars. Nearby items are collected once."),TEXT("F1 guide / ESC pause / N restart. Change modes from the main menu.")}},
{TEXT("街区争夺：视野、道具与3D"),TEXT("STREET WAR: VISION, ITEMS & 3D"), {TEXT("我方半场与地图外可见；敌方半场只显示己方单位附近视野。"),TEXT("右键藏身点进入埋伏，移动离开；近距离搜索会暴露藏身者。"),TEXT("右键道具可手动拾取；受伤或接近失败会中止，不会凭空消耗。"),TEXT("Tab切换俯视与3D街景；F2或全图按钮快速返回地图。"),TEXT("3D左键选兵；右键短点下令、按住拖动转向。"),TEXT("WASD移动镜头，滚轮缩放；Home聚焦，T跟随选中角色。"),TEXT("选中角色后进入3D可跟随观察；手动移动镜头会取消跟随。"),TEXT("现金用于招募，黄金用于胜利；运输与拾取期间注意保护队友。")}, {TEXT("Your half and outside the field are visible; scout the enemy half with your units."),TEXT("RMB a hideout to hide; move to leave. Close searches reveal hidden occupants."),TEXT("RMB an item to collect it. Damage or failed approach cancels without consuming it."),TEXT("TAB switches overhead / 3D street view. F2 or MAP restores the full map."),TEXT("In 3D: LMB selects; short RMB clicks command; hold and drag RMB to look."),TEXT("WASD moves the camera; wheel zooms; HOME frames selection; T follows it."),TEXT("Entering 3D with a selected role follows it. Manual camera movement stops following."),TEXT("Cash buys recruits; banked gold wins. Protect couriers while collecting and delivering.")}},
{TEXT("街区争夺：事件与胜负"),TEXT("STREET WAR: EVENTS & VICTORY"), {TEXT("开局3袋随机黄金；运回基地入库，500黄金保持15秒获胜。"),TEXT("普通运金车在1:00、2:10、3:20出现，提前30秒预告位置。"),TEXT("普通车2名护卫；击败护卫后右键开货，护送黄金回基地。"),TEXT("摧毁敌方基地车也可直接获胜，注意保护自己的基地血量。"),TEXT("4:00进入后期，10秒宽限后老大倒下会败北，NPC伤害提高。"),TEXT("后期NPC伤害为1.5倍；4:30钻石车出现，有4名护卫。"),TEXT("夺取钻石并运回己方基地直接获胜；携带者会公开标记。"),TEXT("最长6分钟；届时按黄金、基地状态等现有规则裁定胜负。")}, {TEXT("Three gold bags spawn at the start. Bank 500 gold and hold it for 15 seconds to win."),TEXT("Gold convoys arrive at 1:00, 2:10 and 3:20, with a 30-second location warning."),TEXT("Each gold convoy has 2 guards. Defeat them, RMB to open cargo, and carry gold home."),TEXT("Destroy the enemy base van to win. Protect your own van and watch its health."),TEXT("The final phase starts at 4:00. After 10 seconds, losing your boss loses the match."),TEXT("NPC damage becomes 1.5x in the final phase. A diamond convoy with 4 guards arrives at 4:30."),TEXT("Bring the diamond to your base for instant victory. The carrier is publicly marked."),TEXT("The match lasts at most 6 minutes, then gold and base status determine the result.")}},
{TEXT("法则挑战：七轮布阵"),TEXT("RULE RUN: SEVEN WAVES & FORMATION"), {TEXT("初始3名跑腿兵、200金币、3次生命，军团最多20人。"),TEXT("可购买跑腿、刀兵、铁棍、投掷和枪手；枪手使用持枪安保模型。"),TEXT("战前左键选己方单位，再点蓝方地面调整站位；Shift加选。"),TEXT("右键拖框可多选；不能放到敌方半场或与其他单位重叠。"),TEXT("开战前可观察敌方阵容；空格开战，最多7轮，第7轮为决战。"),TEXT("近战在前排、远程留后排；每关敌阵和兵力逐步变化。"),TEXT("战斗中右键地面移动、敌人集火，Shift加选。"),TEXT("恢复默认阵型可重新排布；购买前先留出部署空间。")}, {TEXT("Start with 3 runners, 200 gold and 3 lives. Your army can hold 20 soldiers."),TEXT("Recruit runners, blades, batons, throwers and gunners. Gunners use the armed guard model."),TEXT("Before battle: LMB an ally, then click blue ground to place it. SHIFT adds units."),TEXT("Drag RMB for squads. You cannot deploy in enemy territory or overlap soldiers."),TEXT("Inspect enemy formations before pressing SPACE. Clear 7 waves to win the run."),TEXT("Place melee units in front and ranged units behind. Enemy composition grows each wave."),TEXT("During battle, RMB ground to move or RMB an enemy to focus fire. SHIFT adds selections."),TEXT("AUTO FORMATION resets your layout. Leave room for recruits before buying them.")}},
{TEXT("法则挑战：24法则与刷新"),TEXT("RULE RUN: 24 LAWS & REROLLS"), {TEXT("每次通关后从3个候选中选1条法则，确认后进入补给商店。"),TEXT("共有24种法则：击退、重力、机动、近战、远程、回复等。"),TEXT("每次选法则可免费刷新整组候选一次；不会扣金币。"),TEXT("刷新会清除原选择；必须重新点选并确认，不能重复刷新。"),TEXT("商店刷新另计20金币，与法则免费刷新无关。"),TEXT("获得的法则在本局后续关卡持续有效，卡片说明影响己方或双方。"),TEXT("部分法则有取舍：例如重装增血但减速；叠加属性有安全上限。"),TEXT("脱战回复需3秒未受敌方伤害；吸血按实际伤害，不能超过满血。")}, {TEXT("After a win, choose 1 of 3 laws and confirm to enter the supply shop."),TEXT("There are 24 laws covering gravity, knockback, mobility, melee, ranged attacks and healing."),TEXT("Each law draft has ONE FREE REROLL of all three offers. It costs no gold."),TEXT("Rerolling clears your selection. Choose again before confirming; rerolls cannot be repeated."),TEXT("Shop refresh costs 20 gold and is separate from the free law reroll."),TEXT("Chosen laws persist for the run. Read each card to see which team it affects."),TEXT("Some laws have tradeoffs, such as more health but less speed. Stacked bonuses have limits."),TEXT("Regeneration starts 3 seconds after an enemy hit. Lifesteal uses actual damage and caps at full health.")}},
{TEXT("法则挑战：结算与操作"),TEXT("RULE RUN: RESULTS & CONTROLS"), {TEXT("购买的单位本局保留，下一关满血返回；战斗成长会重置。"),TEXT("失败扣1次生命，可重新布阵挑战同一关；3次生命耗尽结束。"),TEXT("胜利获得关卡和存活奖励，再选法则、购买兵种和重新布阵。"),TEXT("45秒场地开始收缩；65秒按双方剩余生命比例总和裁决。"),TEXT("WASD平移，中键旋转，滚轮缩放；Home重置镜头。"),TEXT("本模式Tab切换0.5/1/2倍速，不用于进入3D街景。"),TEXT("F1指南，ESC暂停，N开始新一局；返回主菜单会结束本次挑战。"),TEXT("主菜单可切换中英文；成就收藏记录招募、击杀和通关足迹。")}, {TEXT("Purchased units stay for the run and return at full health next wave. Battle growth resets."),TEXT("A loss costs 1 life. Redeploy and retry the same wave; losing all 3 lives ends the run."),TEXT("Winning grants wave and survivor rewards, then a law draft, shop and deployment."),TEXT("The field starts shrinking at 45 seconds. At 65 seconds, remaining health fractions decide the winner."),TEXT("WASD pans; MMB drag rotates; wheel zooms; HOME resets the camera."),TEXT("TAB cycles 0.5x / 1x / 2x speed in this mode; it does not enter street view."),TEXT("F1 guide / ESC pause / N new run. Returning to the main menu ends this run."),TEXT("Switch Chinese / English from the menu. Collection records recruitment, kills and victories.")}},
};}
void UKTWSession::DrawGuide(AKTWPrototypeHUD* H){auto* C=H->GameCanvas();const float W=C->SizeX,V=C->SizeY,S=FMath::Min(W/1600.f,V/900.f);const float X=W*.08f,Y=V*.08f,BW=W*.84f;Buttons.Empty();H->DrawRect(FLinearColor(.008f,.019f,.028f,.99f),X,Y,BW,V*.84f);H->DrawRect(FLinearColor(.03f,.88f,.91f,1),X,Y,BW,3*S);const auto& P=Pages[FMath::Clamp(ModeChoice,0,1)*3+FMath::Clamp(HelpPage,0,2)];H->DrawText(English?P.EN:P.CN,FLinearColor(.9f,.94f,.94f,1),X+32*S,Y+28*S,nullptr,1.5f*S);for(int I=0;I<8;++I)H->DrawText(FString::Printf(TEXT("%d   %s"),I+1,English?P.LinesEN[I]:P.LinesCN[I]),FLinearColor(.83f,.89f,.90f,1),X+32*S,Y+(105+I*54)*S,nullptr,.94f*S);
 auto Button=[&](FString Id,FString Title,float BX){const FVector4 R(BX,Y+V*.70f,BW*.28f,48*S);H->DrawRect(FLinearColor(.06f,.13f,.17f,1),R.X,R.Y,R.Z,R.W);H->DrawText(Title,FLinearColor::White,R.X+18*S,R.Y+12*S,nullptr,S);FKTWMenuButton B;B.Id=Id;B.Text=Title;B.Rect=R;B.Enabled=true;Buttons.Add(B);};Button(TEXT("Prev"),English?TEXT("PREVIOUS"):TEXT("上一页"),X+32*S);Button(TEXT("Next"),English?TEXT("NEXT"):TEXT("下一页"),X+BW*.36f);Button(TEXT("Back"),English?TEXT("BACK / RESUME"):TEXT("返回 / 继续游戏"),X+BW*.69f);H->DrawText(FString::Printf(TEXT("%d / 3"),HelpPage+1),FLinearColor(.03f,.88f,.91f,1),X+BW-100*S,Y+30*S,nullptr,S);
#if !UE_BUILD_SHIPPING
 if(FParse::Param(FCommandLine::Get(),TEXT("KTWGuideCapture"))){static bool Started=false;if(!Started){Started=true;for(int I=0;I<12;++I){FTimerHandle T;GetWorld()->GetTimerManager().SetTimer(T,[this,I](){English=I>=6;ModeChoice=(I%6)/3;HelpPage=I%3;},.3f+I*1.1f,false);FTimerHandle Shot;GetWorld()->GetTimerManager().SetTimer(Shot,[I](){FScreenshotRequest::RequestScreenshot(FPaths::ProjectSavedDir()/FString::Printf(TEXT("Screenshots/Guide_%02d.png"),I),true,false);},.8f+I*1.1f,false);}FTimerHandle End;GetWorld()->GetTimerManager().SetTimer(End,[](){UE_LOG(LogTemp,Display,TEXT("KTW GUIDE CAPTURE COMPLETE"));FPlatformMisc::RequestExit(false);},14.2f,false);}}
#endif
}
